import random
from collections import deque

def check_add_edge(adj, u, v, max_cycle_len=5):
    # Check if adding edge (u,v) creates a cycle of length <= max_cycle_len
    # We need to check if there is a path from u to v of length 2,3,4 (for max_cycle_len=5)
    # BFS from u, avoiding v, up to depth max_cycle_len-1
    # Actually we need path lengths 2,3,4 (since edge (u,v) would close cycle of length 3,4,5)
    # So check distances from u to v in current graph. If distance d exists with 2 <= d <= 4, then adding (u,v) creates cycle of length d+1.
    # BFS up to depth 4.
    if v in adj[u]:
        return False
    visited = {u: 0}
    q = deque([u])
    while q:
        cur = q.popleft()
        d = visited[cur]
        if d >= 4:  # we only care about paths of length <=4
            continue
        for nb in adj[cur]:
            if nb == v:
                if d+1 <= 4:
                    return False
                else:
                    continue
            if nb not in visited:
                visited[nb] = d+1
                q.append(nb)
    return True

def greedy_random(seed=None):
    if seed is not None:
        random.seed(seed)
    n = 14
    adj = {i: set() for i in range(n)}
    edges = [(i,j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(edges)
    added = []
    for u,v in edges:
        if check_add_edge(adj, u, v):
            adj[u].add(v)
            adj[v].add(u)
            added.append((u,v))
    return added, adj

