from z3 import *

def solve_graph_z3():
    n = 14
    colors = 4
    min_edges = 26

    # Edge variables
    edges = {}
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = Bool(f"e_{i}_{j}")

    # Color variables
    color_vars = {}
    for i in range(n):
        for c in range(colors):
            color_vars[(i,c)] = Bool(f"c_{i}_{c}")

    s = Solver()

    # Each vertex has exactly one color
    for i in range(n):
        s.add(Or([color_vars[(i,c)] for c in range(colors)]))
        for c1 in range(colors):
            for c2 in range(c1+1, colors):
                s.add(Not(And(color_vars[(i,c1)], color_vars[(i,c2)])))

    # Proper coloring: if edge exists, endpoints have different colors
    for i in range(n):
        for j in range(i+1, n):
            e = edges[(i,j)]
            for c in range(colors):
                s.add(Not(And(e, color_vars[(i,c)], color_vars[(j,c)])))

    # No 3-cycles
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))
                count += 1
    print(f"3-cycle constraints: {count}")

    # No 4-cycles
    count4 = 0
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                for d in range(c+1, n):
                    # All 4-cycles on {a,b,c,d}: there are 3 distinct cycles
                    # (a-b-c-d-a), (a-b-d-c-a), (a-c-b-d-a)
                    # But we need to be careful with edge ordering
                    verts = [a,b,c,d]
                    # Generate all Hamiltonian cycles
                    from itertools import permutations
                    seen = set()
                    for perm in permutations(verts):
                        if perm[0] != a: continue  # fix starting point
                        # canonical form
                        cycle = tuple(sorted([(min(perm[i], perm[(i+1)%4]), max(perm[i], perm[(i+1)%4])) for i in range(4)]))
                        if cycle in seen:
                            continue
                        seen.add(cycle)
                        s.add(Not(And([edges[e] for e in cycle])))
                        count4 += 1
    print(f"4-cycle constraints: {count4}")

    # No 5-cycles
    count5 = 0
    from itertools import combinations, permutations
    for verts in combinations(range(n), 5):
        a = verts[0]
        seen = set()
        for perm in permutations(verts):
            if perm[0] != a:
                continue
            cycle = tuple(sorted([(min(perm[i], perm[(i+1)%5]), max(perm[i], perm[(i+1)%5])) for i in range(5)]))
            if cycle in seen:
                continue
            seen.add(cycle)
            s.add(Not(And([edges[e] for e in cycle])))
            count5 += 1
    print(f"5-cycle constraints: {count5}")

    # At least 26 edges
    # Use PbGe
    s.add(PbGe([(edges[e], 1) for e in edges], min_edges))

    print("Solving...")
    result = s.check()
    print(f"Result: {result}")
    if result == sat:
        m = s.model()
        edge_list = []
        for e in edges:
            if is_true(m[edges[e]]):
                edge_list.append(e)
        print(f"Edges: {len(edge_list)}")
        print(edge_list)

        # Verify coloring
        coloring = {}
        for i in range(n):
            for c in range(colors):
                if is_true(m[color_vars[(i,c)]]):
                    coloring[i] = c
                    break
        print(f"Coloring: {coloring}")
        return edge_list, coloring
    else:
        return None, None

