from pysat.solvers import Solver
from pysat.card import CardEnc

def solve_with_pysat():
    n = 14
    colors = 4
    min_edges = 26

    # Map each variable to an integer
    var_map = {}
    counter = 1

    # Edge variables: 1..91
    edges = {}
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = counter
            var_map[counter] = ('e', i, j)
            counter += 1

    # Color variables
    color_vars = {}
    for i in range(n):
        for c in range(colors):
            color_vars[(i,c)] = counter
            var_map[counter] = ('c', i, c)
            counter += 1

    clauses = []

    # Each vertex has at least one color
    for i in range(n):
        clauses.append([color_vars[(i,c)] for c in range(colors)])

    # Each vertex has at most one color
    for i in range(n):
        for c1 in range(colors):
            for c2 in range(c1+1, colors):
                clauses.append([-color_vars[(i,c1)], -color_vars[(i,c2)]])

    # Proper coloring: if edge exists, endpoints have different colors
    for i in range(n):
        for j in range(i+1, n):
            e = edges[(i,j)]
            for c in range(colors):
                clauses.append([-e, -color_vars[(i,c)], -color_vars[(j,c)]])

    # No 3-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                clauses.append([-edges[(i,j)], -edges[(j,k)], -edges[(i,k)]])

    # No 4-cycles
    from itertools import permutations
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                for d in range(c+1, n):
                    verts = [a,b,c,d]
                    seen = set()
                    for perm in permutations(verts):
                        if perm[0] != a:
                            continue
                        cycle = tuple(sorted([(min(perm[i], perm[(i+1)%4]), max(perm[i], perm[(i+1)%4])) for i in range(4)]))
                        if cycle in seen:
                            continue
                        seen.add(cycle)
                        clauses.append([-edges[e] for e in cycle])

    # No 5-cycles
    from itertools import combinations
    for verts in combinations(range(n), 5):
        a = verts[0]
        seen = set()
        for perm in permutations(verts):
            if perm[0] != a:
                continue
            cycle = tuple(sorted([(min(perm[i], perm[(i+1)%5]), max(perm[i], perm[(i+1)%5])) for i in range(5)]))
            if cycle in seen:
                continue
            seen.add(cycle)
            clauses.append([-edges[e] for e in cycle])

    print(f"Total clauses: {len(clauses)}")
    print(f"Total variables: {counter-1}")

    # At least 26 edges - use cardinality constraint
    edge_vars = [edges[e] for e in edges]
    card_clauses = CardEnc.atleast(lits=edge_vars, bound=min_edges, encoding=CardEnc.totalizer)
    if hasattr(card_clauses, 'clauses'):
        clauses.extend(card_clauses.clauses)
    else:
        clauses.extend(card_clauses)

    print(f"After cardinality: {len(clauses)} clauses")

    with Solver(name='g3') as solver:
        for clause in clauses:
            solver.add_clause(clause)
        print("Solving...")
        sat = solver.solve()
        print(f"SAT: {sat}")
        if sat:
            model = solver.get_model()
            edge_list = []
            for e in edges:
                if edges[e] in model:
                    edge_list.append(e)
            print(f"Edges: {len(edge_list)}")
            print(edge_list)

            coloring = {}
            for i in range(n):
                for c in range(colors):
                    if color_vars[(i,c)] in model:
                        coloring[i] = c
                        break
            print(f"Coloring: {coloring}")
            return edge_list, coloring
    return None, None

